// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Screen Handler (Module 10 v2 — Step 10.4). * * Handles two operations: *  - [SystemOperation.LockScreen] — lock the screen (biometric-friendly *    via AccessibilityService, NOT DevicePolicyManager — Review 2 Fix B). *  - [SystemOperation.SetKeepScreenOn] — toggle "keep screen on" flag. * * ## Lock Screen (Review 2 Fix B) * * **v1 flaw**: `DevicePolicyManager.lockNow()` requires Device Admin. Once * used, the device unlocks with **PIN/password only — biometric (fingerprint/ * face) is broken**. UX disaster. * * **v2 fix**: Use `AccessibilityService.GLOBAL_ACTION_LOCK_SCREEN`. This * triggers a normal lock that preserves biometric unlock. Requires the user * to enable the NOUS Accessibility Service in system Settings. * * If the accessibility service isn't enabled, the handler returns * `Result.Failure(Hardware.Unavailable)` with the message "Accessibility * Service required". The UI then prompts the user to enable it. * * ## Keep Screen On * * Toggles `WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON` on the current * activity's window. Useful for cooking timers, navigation, etc. where the * user wants the screen to stay on. * * Requires a foreground activity — if no activity is available (e.g., NOUS * is running in background), the operation returns `Result.Failure`. * * ## Reversibility * * Lock screen is **not reversible** (you can't "unlock" programmatically — * that would defeat the purpose of a lock). [SetKeepScreenOn] is reversible * — undo clears the flag. * * ## Resource category * * Both operations use [ResourceCategory.DISPLAY]. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Screen Lock</a> */class ScreenHandler(    private val accessibilityService: NousAccessibilityServiceInterface,    private val displayService: DisplayService,) : ReversibleHandler<SystemOperation> {    override val id: String = "screen"    override val displayName: String = "Screen Control"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.DISPLAY    override fun isAvailable(): Boolean = true  // all devices have a screen    override suspend fun execute(operation: SystemOperation): Result<Unit> = when (operation) {        is SystemOperation.LockScreen -> executeLockScreen()        is SystemOperation.SetKeepScreenOn -> executeKeepScreenOn(operation)        else -> Result.Failure(            error = AppError.Hardware.Unsupported("screen:${operation::class.simpleName}"),            correlationId = CorrelationId.generate(),            durationNanos = 0,        )    }    // ─── Lock screen (Review 2 Fix B) ─────────────────────────────────────    private fun executeLockScreen(): Result<Unit> =        HardwareExceptionMapper.withMappingSync("screen") {            if (!accessibilityService.isServiceEnabled()) {                return@withMappingSync Result.Failure(                    error = AppError.Hardware.Unavailable(                        resource = "accessibility_service",                        cause = null,                    ),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }            val success = accessibilityService.performGlobalAction(                AccessibilityActions.GLOBAL_ACTION_LOCK_SCREEN,            )            if (success) {                Result.Success(Unit, CorrelationId.generate(), 0)            } else {                Result.Failure(                    error = AppError.Hardware.Unknown("screen_lock"),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    // ─── Keep screen on ────────────────────────────────────────────────────    private fun executeKeepScreenOn(op: SystemOperation.SetKeepScreenOn): Result<Unit> =        HardwareExceptionMapper.withMappingSync("screen") {            val applied = displayService.setKeepScreenOn(op.enabled)            if (applied) {                Result.Success(Unit, CorrelationId.generate(), 0)            } else {                Result.Failure(                    error = AppError.Hardware.Unavailable("foreground_window"),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    // ─── Pre-state capture ─────────────────────────────────────────────────    /**     * Pre-state capture — only meaningful for [SetKeepScreenOn].     *     * LockScreen is not reversible, so pre-state is null.     */    override suspend fun capturePreState(operation: SystemOperation): Any? {        return when (operation) {            is SystemOperation.SetKeepScreenOn -> {                // We can't read the current flag from DisplayService (it's write-only                // from outside the activity). Return a sentinel that restorePreState                // uses to toggle back.                KeepScreenOnPreState(previousEnabled = !operation.enabled)            }            else -> null  // LockScreen — not reversible        }    }    override suspend fun restorePreState(operation: SystemOperation, preState: Any?) {        if (operation !is SystemOperation.SetKeepScreenOn) return        if (preState !is KeepScreenOnPreState) return        try {            displayService.setKeepScreenOn(preState.previousEnabled)        } catch (t: Throwable) {            Timber.tag("ScreenHandler").w("Failed to restore keep-screen-on", t)        }    }    // ─── Idempotent check ──────────────────────────────────────────────────    override suspend fun getCurrentState(): Any? = null  // can't read window flag externally    override suspend fun isAlreadyInTargetState(operation: SystemOperation): Boolean {        // LockScreen — never idempotent (locking twice is harmless but not a "skip").        // SetKeepScreenOn — can't read current flag, so never claim idempotent.        return false    }    override fun describeOperation(operation: SystemOperation): String = when (operation) {        is SystemOperation.LockScreen -> "Screen locked"        is SystemOperation.SetKeepScreenOn ->            if (operation.enabled) "Keep screen on enabled" else "Keep screen on disabled"        else -> "Screen operation"    }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is KeepScreenOnPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"KeepScreenOnPreState\",\"previousEnabled\":${preState.previousEnabled}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "KeepScreenOnPreState" -> KeepScreenOnPreState(                previousEnabled = (map["previousEnabled"] as? Boolean) ?: false,            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Pre-state for keep-screen-on (toggles back on undo). */    data class KeepScreenOnPreState(val previousEnabled: Boolean)}
